#include <iostream>

int squareByValue(int number) {
    return number *= number; // Only local copy modified
}

void squareByReference(int& numberRef) {
    numberRef *= numberRef; // Caller's argument modified
}

int main() {
    int x = 2;
    int z = 4;

    std::cout << "x = " << x << " before squareByValue\n";
    std::cout << "Value returned by squareByValue: " << squareByValue(x) << "\n";
    std::cout << "x = " << x << " after squareByValue\n\n";

    std::cout << "z = " << z << " before squareByReference\n";
    squareByReference(z);
    std::cout << "z = " << z << " after squareByReference\n";

    return 0;
}

#include <iostream>

// Safe: accepts const reference (avoids copy, read-only)
void displayCube(const double& side) {
    std::cout << "Cube volume: " << (side * side * side) << "\n";
}

// Safe: returns reference to a static variable
int& getStaticCounter() {
    static int count = 0;
    ++count;
    return count;
}

int main() {
    int original = 10;
    int& alias = original; // Local reference alias
    alias += 5;
    std::cout << "original: " << original << ", alias: " << alias << "\n";

    double edge = 3.5;
    displayCube(edge);
    displayCube(2.0); // Allowed: const ref binds to temporary rvalue

    int& refCount = getStaticCounter();
    std::cout << "Counter: " << refCount << "\n";
    refCount = 100; // Modifying value via returned reference
    std::cout << "Updated Counter: " << getStaticCounter() << "\n";

    return 0;
}

#include <iostream>

// Inline function calculating cube
inline double cube(const double side) {
    return side * side * side;
}

// Function prototype specifying default trailing arguments
unsigned int boxVolume(unsigned int length = 1, unsigned int width = 1, unsigned int height = 1);

int main() {
    // Inline invocation
    double edge = 3.5;
    std::cout << "Volume of cube with side " << edge << " is " << cube(edge) << "\n";

    // Using default arguments
    std::cout << "Default box volume: " << boxVolume() << "\n";
    std::cout << "Length 10, default width/height: " << boxVolume(10) << "\n";
    std::cout << "Length 10, width 5, default height: " << boxVolume(10, 5) << "\n";
    std::cout << "All dimensions specified (10, 5, 2): " << boxVolume(10, 5, 2) << "\n";

    return 0;
}

// Function definition (defaults must NOT be repeated here)
unsigned int boxVolume(unsigned int length, unsigned int width, unsigned int height) {
    return length * width * height;
}
